/*!
 * syno_beautify —— Synology Note Station 一键美化（排版 + 表格）
 *
 * 设计要点
 *  1. 只改元素的 style 属性，不动 DOM 结构 —— 不破坏光标、选区、撤销栈之外的任何东西。
 *  2. 全部写成「内联样式」，随笔记 HTML 一起存储/同步 ——
 *     DSM 网页版、手机 App、导出 HTML 都是同一套观感（纯 CSS 类做不到这点）。
 *  3. 幂等：重复点击结果一致；Cmd+Z 可整体撤销。
 *
 * 用法
 *  工具栏「美化」按钮：美化整篇（字体 / 字号 / 行距 / 段距 / 标题 / 列表 / 引用 / 代码 / 表格）
 *  按住 Option 点击：只美化表格
 *  快捷键：Ctrl(Cmd) + Alt + B
 */
(function () {
    'use strict';

    /* ------------------------------------------------------------------ *
     * 预设：想调风格只改这里
     * ------------------------------------------------------------------ */
    var SANS = '-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB",' +
        '"Microsoft YaHei","Helvetica Neue",Arial,sans-serif';
    var MONO = 'SFMono-Regular,Menlo,Consolas,"Liberation Mono","Courier New",monospace';

    var P = {
        font: SANS,
        size: '15px',       // 正文
        lh: '1.85',         // 正文行距
        color: '#2f3b4a',   // 正文色
        gap: '12px',        // 段间距（下外边距）
        listGap: '4px',     // 列表项间距
        indent: '26px'      // 列表缩进
    };

    // 表格配色
    var T = {
        border: '#d7e1eb',
        headBg: '#f2f6fa',
        headColor: '#1f3547',
        stripeBg: '#fafcfe',
        cellBg: '#ffffff',
        cellColor: '#33475b',
        size: '14px',
        padHead: '9px 12px',
        padCell: '8px 12px',
        margin: '14px 0'
    };

    // 标题：字号 / 行高 / 上外边距 / 下外边距 / 字重 / 颜色
    var HEADS = {
        H1: ['24px', '1.45', '26px', '12px', '700', '#16283a'],
        H2: ['20px', '1.50', '22px', '10px', '700', '#1a2f44'],
        H3: ['17px', '1.55', '18px', '8px', '600', '#1f3547'],
        H4: ['15.5px', '1.60', '16px', '8px', '600', '#243b4f'],
        H5: ['15px', '1.60', '14px', '6px', '600', '#2b4157'],
        H6: ['14px', '1.60', '14px', '6px', '600', '#5a6b7c']
    };

    /* ------------------------------------------------------------------ *
     * 工具
     * ------------------------------------------------------------------ */
    function setStyle(el, map) {
        for (var k in map) {
            if (!Object.prototype.hasOwnProperty.call(map, k)) { continue; }
            var v = map[k];
            if (v === null || v === undefined || v === '') {
                try { el.style.removeProperty(k); } catch (e) { /* ignore */ }
            } else {
                try { el.style.setProperty(k, v); } catch (e2) { /* ignore */ }
            }
        }
    }

    function closest(el, sel) {
        if (typeof el.closest === 'function') {
            return el.closest(sel);
        }
        while (el && el.nodeType === 1) {
            if (el.matches && el.matches(sel)) { return el; }
            el = el.parentNode;
        }
        return null;
    }

    /* ------------------------------------------------------------------ *
     * 表格
     * ------------------------------------------------------------------ */
    function beautifyTable(t) {
        setStyle(t, {
            'border-collapse': 'collapse',
            'border-spacing': '0',
            'table-layout': 'auto',
            'width': '100%',
            'max-width': '100%',
            'margin': T.margin,
            'font-size': T.size,
            'line-height': '1.7'
        });

        var hasHead = !!t.tHead;

        function paintRow(tr, isHead, stripe) {
            for (var c = 0; c < tr.cells.length; c++) {
                var cell = tr.cells[c];
                var align = (cell.getAttribute('align') || '').toLowerCase();
                var st = {
                    'border': '1px solid ' + T.border,
                    'padding': isHead ? T.padHead : T.padCell,
                    'vertical-align': 'top',
                    'word-break': 'break-word',
                    'font-family': P.font,   // skin 里 td/th 自带 Verdana，必须显式覆盖
                    'font-size': T.size,
                    'line-height': '1.68',
                    'font-weight': isHead ? '600' : '400',
                    'color': isHead ? T.headColor : T.cellColor,
                    'background-color': isHead ? T.headBg : (stripe ? T.stripeBg : T.cellBg)
                };
                if (align === 'left' || align === 'right' || align === 'center') {
                    st['text-align'] = align;
                }
                setStyle(cell, st);
            }
        }

        // thead
        if (hasHead) {
            for (var h = 0; h < t.tHead.rows.length; h++) {
                paintRow(t.tHead.rows[h], true, false);
            }
        }

        // tbody（Note Station 自带表格没有 thead，首行即表头）
        var rows = [];
        for (var b = 0; b < t.tBodies.length; b++) {
            for (var r = 0; r < t.tBodies[b].rows.length; r++) {
                rows.push(t.tBodies[b].rows[r]);
            }
        }
        var offset = hasHead ? 0 : 1;
        for (var i = 0; i < rows.length; i++) {
            var isHeadRow = !hasHead && i === 0;
            var stripe = !isHeadRow && ((i - offset) % 2 === 1);
            paintRow(rows[i], isHeadRow, stripe);
        }
    }

    /* ------------------------------------------------------------------ *
     * 排版
     * ------------------------------------------------------------------ */
    function styleHeading(el, tag) {
        var m = HEADS[tag];
        setStyle(el, {
            'margin': m[2] + ' 0 ' + m[3],
            'font-size': m[0],
            'line-height': m[1],
            'font-weight': m[4],
            'color': m[5],
            'font-family': P.font
        });
    }

    function stylePre(el) {
        setStyle(el, {
            'margin': '16px 0',
            'padding': CB.pad,
            'background-color': CB.bg,
            'border': '1px solid ' + CB.border,
            'border-left': '3px solid ' + CB.accent,
            'border-radius': CB.radius,
            'box-shadow': '0 1px 2px rgba(31,53,71,.04)',
            'font-family': MONO,
            'font-size': CB.size,
            'line-height': CB.lh,
            'color': CB.color,
            'tab-size': '4',
            'overflow-x': 'auto',
            'white-space': 'pre-wrap',
            'word-break': 'break-word'
        });
        // 高亮是按 span 着色的，块内的 code 不能再带自己的底色，否则整行糊成一块
        var codeEl = el.querySelector('code');
        if (codeEl) {
            setStyle(codeEl, {
                'background-color': 'transparent',
                'color': 'inherit',
                'padding': '0',
                'border-radius': '0',
                'font-size': 'inherit',
                'font-family': 'inherit'
            });
        }
    }

    function styleCode(el) {
        setStyle(el, {
            'background-color': '#eef2f8',
            'color': '#b3395b',
            'padding': '2px 6px',
            'border-radius': '4px',
            'font-family': MONO,
            'font-size': '0.9em',
            'word-break': 'break-word'
        });
    }

    /* ================================================================== *
     * 代码块：语言识别 + 自动格式化 + 语法高亮
     *
     * 1) 只清理空白（行尾空格 / Tab→4 空格 / 连续空行 / 首尾空行），
     *    不做「重排版式」的缩进重构 —— 那会改坏 Python 缩进、Go 对齐等。
     * 2) 语言优先取 data-md-lang（Markdown 围栏），否则按内容猜。
     * 3) 高亮写成 span 内联 style，跟笔记 HTML 一起存/同步，三端一致。
     * 4) 幂等：每次先把自己上次生成的 span.nsh 拆掉再重新生成。
     * ================================================================== */

    // 代码块外观 + token 配色（浅色主题，与正文/表格同一套冷灰蓝）
    var CB = {
        bg: '#f8fafc',
        border: '#e4eaf2',
        accent: '#b9cde5',
        radius: '8px',
        pad: '14px 18px',
        size: '13px',
        lh: '1.7',
        color: '#33475b',
        cmt: '#93a1b1',   // 注释
        str: '#2e7d5b',   // 字符串
        num: '#a8621a',   // 数字 / 字面量 / 变量
        kw: '#9a3ba8',    // 关键字
        fn: '#3468d1',    // 函数名 / 对象键 / 属性名
        tag: '#3468d1',   // 标签名
        attr: '#9a3ba8'   // 属性名
    };

    // 语言别名 -> 规范名
    var LANG_ALIAS = {
        javascript: 'js', jsx: 'js', mjs: 'js', cjs: 'js', node: 'js',
        typescript: 'ts', tsx: 'ts',
        py: 'python', python3: 'python',
        sh: 'bash', shell: 'bash', zsh: 'bash', console: 'bash', shellscript: 'bash',
        golang: 'go', rs: 'rust', kt: 'kotlin', rb: 'ruby',
        'c++': 'cpp', cxx: 'cpp', cc: 'cpp', hpp: 'cpp', h: 'c',
        'c#': 'csharp', cs: 'csharp',
        yml: 'yaml', htm: 'html', html5: 'html', xhtml: 'html', vue: 'html', svg: 'html',
        json5: 'json', jsonc: 'json', patch: 'diff'
    };

    var KW_JS = 'async await break case catch class const continue debugger default delete do else export extends ' +
        'finally for from function get if import in instanceof let new of return set static super switch ' +
        'throw try typeof var void while with yield';
    var KW_TS = KW_JS + ' interface type enum implements declare namespace readonly abstract as satisfies ' +
        'keyof infer public private protected is asserts';
    var KW_JAVA = 'abstract assert boolean break byte case catch char class const continue default do double else ' +
        'enum extends final finally float for goto if implements import instanceof int interface long native new ' +
        'package private protected public record return sealed short static strictfp super switch synchronized ' +
        'this throw throws transient try var void volatile while yield';
    var KW_PY = 'and as assert async await break class continue def del elif else except finally for from global ' +
        'if import in is lambda nonlocal not or pass raise return try while with yield match case';
    var KW_GO = 'break case chan const continue default defer else fallthrough for func go goto if import ' +
        'interface map package range return select struct switch type var';
    var KW_RUST = 'as async await break const continue crate dyn else enum extern fn for if impl in let loop ' +
        'match mod move mut pub ref return self static struct super trait type unsafe use where while';
    var KW_C = 'auto break case char const continue default do double else enum extern float for goto if inline ' +
        'int long register restrict return short signed sizeof static struct switch typedef union unsigned ' +
        'void volatile while';
    var KW_CS = 'abstract as base bool break byte case catch char checked class const continue decimal default ' +
        'delegate do double else enum event explicit extern finally fixed float for foreach goto if implicit in ' +
        'int interface internal is lock long namespace new object operator out override params private ' +
        'protected public readonly ref return sbyte sealed short sizeof stackalloc static string struct switch ' +
        'throw try typeof uint ulong unchecked unsafe ushort using virtual void volatile while async await var';
    var KW_PHP = 'abstract and array as break callable case catch class clone const continue declare default do ' +
        'echo else elseif empty extends final finally fn for foreach function global goto if implements include ' +
        'include_once instanceof interface isset list namespace new or print private protected public require ' +
        'require_once return static switch throw trait try unset use var while yield';
    var KW_SQL = 'select from where group by order having insert into values update set delete create table ' +
        'alter add column drop index view join left right inner outer full on as and or not null is in like ' +
        'between limit offset union all distinct case when then else end primary key foreign references ' +
        'default constraint unique begin commit rollback transaction if exists int bigint varchar text date ' +
        'datetime timestamp decimal numeric char float double boolean';
    var KW_SH = 'if then else elif fi for while until do done case esac function return in export local ' +
        'readonly declare unset source alias echo cd pwd exit set shift eval exec trap test';

    var SPEC = {
        js: { kw: KW_JS, lit: 'true false null undefined NaN Infinity this', line: ['//'], block: [['/*', '*/']], str: ['"', "'", '`'], multi: '`' },
        ts: { kw: KW_TS, lit: 'true false null undefined NaN Infinity this', line: ['//'], block: [['/*', '*/']], str: ['"', "'", '`'], multi: '`' },
        json: { kw: '', lit: 'true false null', line: [], block: [], str: ['"'], keyColon: true },
        java: { kw: KW_JAVA, lit: 'true false null', line: ['//'], block: [['/*', '*/']], str: ['"', "'"] },
        python: { kw: KW_PY, lit: 'True False None self cls NotImplemented Ellipsis', line: ['#'], block: [], str: ['"', "'"], triple: true },
        go: { kw: KW_GO, lit: 'true false nil iota', line: ['//'], block: [['/*', '*/']], str: ['"', "'", '`'], multi: '`' },
        rust: { kw: KW_RUST, lit: 'true false None Some Ok Err String Vec', line: ['//'], block: [['/*', '*/']], str: ['"'], multi: true },
        c: { kw: KW_C, lit: 'NULL', line: ['//'], block: [['/*', '*/']], str: ['"', "'"], pp: true },
        cpp: { kw: KW_C + ' class namespace template typename public private protected virtual new delete nullptr using try catch throw operator friend explicit constexpr noexcept bool', lit: 'NULL true false nullptr', line: ['//'], block: [['/*', '*/']], str: ['"', "'"], pp: true },
        csharp: { kw: KW_CS, lit: 'true false null', line: ['//'], block: [['/*', '*/']], str: ['"', "'"], pp: true },
        php: { kw: KW_PHP, lit: 'true false null', line: ['//', '#'], block: [['/*', '*/']], str: ['"', "'"], dollar: true },
        ruby: { kw: 'alias and begin break case class def defined do else elsif end ensure false for if in module next nil not or redo rescue retry return self super then true undef unless until when while yield require attr_accessor', lit: 'true false nil self', line: ['#'], block: [], str: ['"', "'"], dollar: true },
        sql: { kw: KW_SQL, lit: 'null true false', ci: true, line: ['--'], block: [['/*', '*/']], str: ["'", '"'] },
        bash: { kw: KW_SH, lit: 'true false', line: ['#'], block: [], str: ['"', "'"], dollar: true },
        css: { kw: '', line: [], block: [['/*', '*/']], str: ['"', "'"], keyColon: true },
        yaml: { kw: 'true false null yes no on off', line: ['#'], block: [], str: ['"', "'"], keyColon: true },
        html: { markup: true },
        xml: { markup: true }
    };

    // 粘性正则（y）：从 lastIndex 处匹配，避免 src.slice(i) 的 O(n²) 拷贝
    var RE_IDENT_Y = /[A-Za-z_$][\w$]*/y;
    var RE_VAR_Y = /\$[\w$]+/y;
    var RE_NUM_Y = /(?:0[xXbBoO][0-9a-fA-F_]+|(?:\d[\d_]*\.?[\d_]*|\.\d+)(?:[eE][+-]?\d+)?)(?:[A-Za-z%]+)?/y;

    /** 判断 w 是否在空格分隔的词表里（ci=true 时不区分大小写） */
    function inSet(set, w, ci) {
        if (!set) { return false; }
        var hay = ' ' + (ci ? set.toLowerCase() : set) + ' ';
        return hay.indexOf(' ' + (ci ? w.toLowerCase() : w) + ' ') >= 0;
    }

    function startsWithAt(s, p, at) {
        return s.substr(at, p.length) === p;
    }

    /** 从 i 起跳过空格/制表符，返回下一个有意义的字符位置 */
    function skipSpace(s, i) {
        var n = s.length;
        while (i < n) {
            var c = s.charCodeAt(i);
            if (c !== 32 && c !== 9) { break; }
            i += 1;
        }
        return i;
    }

    /** 通用词法扫描：注释 / 字符串 / 数字 / 标识符 -> token 序列 */
    function tokenize(src, sp) {
        var out = [];
        var buf = '';
        var n = src.length;
        var i = 0;
        var ci = !!sp.ci;

        function flush() {
            if (buf) { out.push({ t: '', v: buf }); buf = ''; }
        }
        function emit(t, v) {
            if (!v) { return; }
            if (!t) { buf += v; return; }   // 普通文本合并，减少 DOM 节点
            flush();
            out.push({ t: t, v: v });
        }

        while (i < n) {
            var ch = src.charAt(i);
            var k;

            // 预处理指令（#include / #define）：整行算关键字
            if (sp.pp && ch === '#' && (i === 0 || src.charAt(i - 1) === '\n')) {
                var eol = src.indexOf('\n', i);
                eol = (eol < 0) ? n : eol;
                emit('kw', src.slice(i, eol));
                i = eol;
                continue;
            }

            // 行注释
            var hit = false;
            for (k = 0; sp.line && k < sp.line.length; k++) {
                if (startsWithAt(src, sp.line[k], i)) {
                    var e1 = src.indexOf('\n', i);
                    e1 = (e1 < 0) ? n : e1;
                    emit('cmt', src.slice(i, e1));
                    i = e1;
                    hit = true;
                    break;
                }
            }
            if (hit) { continue; }

            // 块注释
            for (k = 0; sp.block && k < sp.block.length; k++) {
                if (startsWithAt(src, sp.block[k][0], i)) {
                    var e2 = src.indexOf(sp.block[k][1], i + sp.block[k][0].length);
                    e2 = (e2 < 0) ? n : e2 + sp.block[k][1].length;
                    emit('cmt', src.slice(i, e2));
                    i = e2;
                    hit = true;
                    break;
                }
            }
            if (hit) { continue; }

            // 字符串
            if (sp.str && sp.str.indexOf(ch) >= 0) {
                var j;
                var q3 = ch + ch + ch;
                if (sp.triple && src.substr(i, 3) === q3) {
                    var t3 = src.indexOf(q3, i + 3);
                    j = (t3 < 0) ? n : t3 + 3;
                } else {
                    j = i + 1;
                    var multi = !!sp.multi && sp.multi.indexOf(ch) >= 0;
                    while (j < n) {
                        var c = src.charAt(j);
                        if (c === '\\') { j += 2; continue; }
                        if (c === ch) { j += 1; break; }
                        if (c === '\n' && !multi) { break; }
                        j += 1;
                    }
                }
                if (j > n) { j = n; }
                var isKey = !!sp.keyColon && src.charAt(skipSpace(src, j)) === ':';
                emit(isKey ? 'fn' : 'str', src.slice(i, j));
                i = j;
                continue;
            }

            // 数字
            if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(src.charAt(i + 1)))) {
                RE_NUM_Y.lastIndex = i;
                var mn = RE_NUM_Y.exec(src);
                if (mn) { emit('num', mn[0]); i += mn[0].length; continue; }
            }

            // $变量
            if (ch === '$' && sp.dollar) {
                RE_VAR_Y.lastIndex = i;
                var mv = RE_VAR_Y.exec(src);
                if (mv) { emit('num', mv[0]); i += mv[0].length; continue; }
            }

            // 标识符 -> 关键字 / 字面量 / 函数名 / 普通
            if (/[A-Za-z_$]/.test(ch)) {
                RE_IDENT_Y.lastIndex = i;
                var w = RE_IDENT_Y.exec(src)[0];
                var after = skipSpace(src, i + w.length);
                if (inSet(sp.kw, w, ci)) {
                    emit('kw', w);
                } else if (inSet(sp.lit, w, ci)) {
                    emit('num', w);
                } else if (src.charAt(after) === '(') {
                    emit('fn', w);
                } else if (sp.keyColon && src.charAt(after) === ':') {
                    emit('fn', w);
                } else {
                    emit('', w);
                }
                i += w.length;
                continue;
            }

            buf += ch;
            i += 1;
        }
        flush();
        return out;
    }

    /** HTML / XML：标签名、属性名、属性值分别着色 */
    function tokenizeMarkup(src) {
        var out = [];
        var re = /<!--[\s\S]*?-->|<!\[CDATA\[[\s\S]*?\]\]>|<![^>]*>|<\/?[A-Za-z][^>]*?\/?>|[^<]+/g;
        var m;
        while ((m = re.exec(src)) !== null) {
            var s = m[0];
            if (s.slice(0, 2) === '<!') { out.push({ t: 'cmt', v: s }); continue; }
            if (s.charAt(0) !== '<') { out.push({ t: '', v: s }); continue; }

            var head = /^(<\/?)([A-Za-z][\w:.-]*)/.exec(s);
            if (!head) { out.push({ t: '', v: s }); continue; }
            out.push({ t: '', v: head[1] });
            out.push({ t: 'tag', v: head[2] });
            var rest = s.slice(head[0].length);

            while (rest.length) {
                var at = /^([\w:.-]+)(\s*=\s*)("[^"]*"|'[^']*'|[^\s"'>]+)?/.exec(rest);
                if (at) {
                    out.push({ t: 'attr', v: at[1] });
                    if (at[2]) { out.push({ t: '', v: at[2] }); }
                    if (at[3]) { out.push({ t: 'str', v: at[3] }); }
                    rest = rest.slice(at[0].length);
                    continue;
                }
                var sp2 = /^[\s]+/.exec(rest);
                if (sp2) { out.push({ t: '', v: sp2[0] }); rest = rest.slice(sp2[0].length); continue; }
                out.push({ t: '', v: rest.charAt(0) });
                rest = rest.slice(1);
            }
        }
        return out;
    }

    /** 按内容猜语言（只在没有 data-md-lang / language-xxx 提示时用） */
    function detectLang(s) {
        var t = String(s).slice(0, 5000);

        // 唯一性高的特征先判
        if (/^\s*[{\[]/.test(t) && /"[^"\n]*"\s*:/.test(t) && t.indexOf('=>') < 0) { return 'json'; }
        if (/^\s*<\?(php|=)/.test(t)) { return 'php'; }
        if (/^\s*(<!DOCTYPE|<html|<\?xml)/i.test(t) ||
            (/<\/[A-Za-z][\w:-]*>/.test(t) && /<[A-Za-z][\w:-]*[^>]*>/.test(t))) { return 'html'; }
        if (/(^|\n)\s*#\s*(include|define|ifndef|pragma)\b/.test(t)) { return 'cpp'; }
        if (/(^|\n)\s*package\s+main\b|(^|\n)\s*func\s+\w+\s*\(/.test(t)) { return 'go'; }
        if (/(^|\n)\s*(pub\s+)?fn\s+\w+\s*[<(]|let\s+mut\b|println!/.test(t)) { return 'rust'; }

        // C#
        if (/(^|\n)\s*using\s+System(\.[\w.]+)?\s*;|Console\.(Write|Read)|(^|\n)\s*namespace\s+[\w.]+\s*\{/.test(t)) { return 'csharp'; }

        // JS / TS：有箭头函数、console./document.、import from 等明确特征
        if (/=>|console\.\w+\(|document\.\w+|window\.\w+|(^|\n)\s*function\s*\w*\s*\(|(^|\n)\s*(const|let)\s+[\w${]|(^|\n)\s*export\s+(default|const|function|class)|(^|\n)\s*import\s+.*\bfrom\b/.test(t)) {
            return /\binterface\s+\w+|:\s*(string|number|boolean)\b|\bas\s+\w+\[\]/.test(t) ? 'ts' : 'js';
        }

        // Java：注解 / java.* 导入 / 修饰符 + 类型声明 / System.out / 抛异常 / 类声明
        if (/(^|\n)\s*import\s+(static\s+)?[\w.]+\s*;/.test(t) ||
            /(^|\n)\s*package\s+[\w.]+\s*;/.test(t) ||
            /(^|\n)\s*@(Override|Autowired|Service|Component|RestController|Controller|Entity|Test|Bean|Transactional)\b/.test(t) ||
            /System\.out\.print/.test(t) ||
            /\bnew\s+\w*(Exception|Error)\s*\(/.test(t) ||
            /(^|\n)\s*(public|private|protected)\s+(static\s+)?(final\s+)?(abstract\s+)?(class|interface|enum|[\w<>\[\], .]+)\s+\w+\s*[=;(]/.test(t) ||
            /(^|\n)\s*(public|private|protected)\s+(abstract\s+)?(class|interface|enum)\b/.test(t)) { return 'java'; }

        // Python
        if (/(^|\n)\s*(def\s+\w+\s*\(|class\s+\w+.*:|from\s+[\w.]+\s+import\b)|(^|\n)\s*import\s+[\w.]+\s*$/m.test(t) ||
            /(^|\n)\s*(if|for|while|with|try)\b[^\n]*:\s*$/m.test(t)) { return 'python'; }

        // SQL
        if (/\b(SELECT|INSERT\s+INTO|UPDATE\s+\w+\s+SET|CREATE\s+TABLE|ALTER\s+TABLE|DELETE\s+FROM)\b/i.test(t) &&
            /\b(FROM|WHERE|VALUES|SET)\b/i.test(t)) { return 'sql'; }

        // Shell
        if (/^\s*#!\/|(^|\n)\s*(if\s*\[\[|fi\b|done\b|echo\s|export\s+\w+=|set\s+-e\b)/.test(t)) { return 'bash'; }

        // CSS / SCSS
        if (/(^|\n)\s*[.#@]?[A-Za-z][\w\s.#:>,\[\]="'-]*\{[^}]*:[^};]*;/.test(t)) { return 'css'; }

        // 兜底：带分号语句 + 大括号 = 类 C 语言，按 JS 着色的关键字覆盖度最好
        if (/(^|\n)[^\n]*;\s*$/m.test(t) && /[{}]/.test(t) && /\(/.test(t)) { return 'js'; }

        if (/(^|\n)\s*[\w.-]+:\s*\S/.test(t) && !/[;{]/.test(t)) { return 'yaml'; }
        return 'plain';
    }

    /**
     * 轻量格式化：只动空白，不动语义。
     * Tab → 4 空格、去行尾空格、连续空行压成一行、去首尾空行；
     * JSON 能解析的话按 2 空格重新序列化（结果确定，安全）。
     */
    function formatCode(text, lang) {
        var t = String(text).replace(/\r\n?/g, '\n').replace(/\u00a0/g, ' ');
        if (lang === 'json') {
            try {
                t = JSON.stringify(JSON.parse(t), null, 2);
            } catch (e) { /* 非法 JSON：保持原文 */ }
        }
        t = t.replace(/[ \t]+$/gm, '');
        t = t.replace(/\t/g, '    ');
        t = t.replace(/\n{3,}/g, '\n\n');
        t = t.replace(/^\n+/, '').replace(/\n+$/, '');
        return t;
    }

    /** 读取代码块纯文本（<br> 与 div/p 视作换行，兼容不同来源的 HTML） */
    function readCodeText(el) {
        var s = '';
        (function walk(node) {
            for (var c = node.firstChild; c; c = c.nextSibling) {
                if (c.nodeType === 3) {
                    s += c.nodeValue;
                } else if (c.nodeType === 1) {
                    if (c.tagName === 'BR') {
                        s += '\n';
                    } else if (c.tagName === 'DIV' || c.tagName === 'P') {
                        walk(c);
                        if (s.charAt(s.length - 1) !== '\n') { s += '\n'; }
                    } else {
                        walk(c);
                    }
                }
            }
        })(el);
        return s;
    }

    /** 拆掉上一次生成的高亮 span，保证重复美化结果一致 */
    function clearHighlight(pre) {
        var spans = pre.querySelectorAll('span.nsh');
        for (var i = spans.length - 1; i >= 0; i--) {
            var sp = spans[i];
            var p = sp.parentNode;
            while (sp.firstChild) { p.insertBefore(sp.firstChild, sp); }
            p.removeChild(sp);
        }
        try { pre.normalize(); } catch (e) { /* ignore */ }
    }

    /** 语言提示：data-md-lang / data-nsh-lang / data-lang / class="language-xxx" */
    function langHint(pre) {
        var v = pre.getAttribute('data-md-lang') || pre.getAttribute('data-nsh-lang') ||
            pre.getAttribute('data-lang') || '';
        var probe = [pre, pre.querySelector('code')];
        for (var i = 0; i < probe.length && !v; i++) {
            var el = probe[i];
            if (!el) { continue; }
            var m = /(?:^|\s)(?:language|lang)-([\w+#.-]+)/.exec(' ' + (el.className || '') + ' ');
            if (m) { v = m[1]; }
        }
        var k = String(v).toLowerCase().replace(/^language-/, '');
        return LANG_ALIAS[k] || k;
    }

    /** 把 token 序列写成 DOM（颜色走内联 style，随笔记存储同步） */
    function renderTokens(node, tokens) {
        var doc = node.ownerDocument || document;
        var frag = doc.createDocumentFragment();
        for (var i = 0; i < tokens.length; i++) {
            var tk = tokens[i];
            if (!tk.t) {
                frag.appendChild(doc.createTextNode(tk.v));
                continue;
            }
            var sp = doc.createElement('span');
            sp.className = 'nsh nsh-' + tk.t;
            sp.setAttribute('style', 'color:' + (CB[tk.t] || CB.color) +
                (tk.t === 'cmt' ? ';font-style:italic' : ''));
            sp.appendChild(doc.createTextNode(tk.v));
            frag.appendChild(sp);
        }
        while (node.firstChild) { node.removeChild(node.firstChild); }
        node.appendChild(frag);
    }

    /**
     * 代码块整形入口：样式 + 自动格式化 + 语法高亮。
     * @param {Element} pre 需要处理的 &lt;pre&gt; 元素
     */
    function polishCode(pre) {
        if (!pre || pre.nodeType !== 1) { return; }
        stylePre(pre);

        var target = pre.querySelector('code') || pre;
        clearHighlight(pre);

        var raw = readCodeText(target);
        if (!raw || !/\S/.test(raw)) {
            return;   // 空代码块：只上样式，保持光标可用
        }

        var lang = langHint(pre);
        if (!SPEC[lang]) { lang = detectLang(raw); }

        var code = formatCode(raw, lang);
        var tokens;
        if (code.length > 200000) {
            tokens = [{ t: '', v: code }];         // 超大块放弃着色，避免卡顿
        } else if (SPEC[lang] && SPEC[lang].markup) {
            tokens = tokenizeMarkup(code);
        } else if (SPEC[lang]) {
            tokens = tokenize(code, SPEC[lang]);
        } else {
            tokens = [{ t: '', v: code }];
        }

        renderTokens(target, tokens);
        try { pre.setAttribute('data-nsh-lang', lang); } catch (e) { /* ignore */ }
    }

    // 供 syno_markdown 在粘贴/生成代码块后自动调用
    try { window.__synoHighlightCode = polishCode; } catch (e) { /* ignore */ }

    function styleQuote(el) {
        setStyle(el, {
            'margin': '14px 0',
            'padding': '10px 16px',
            'border-left': '3px solid #4b8dd8',
            'background-color': '#f4f8fd',
            'border-radius': '0 6px 6px 0',
            'color': '#46586d',
            'font-family': P.font,
            'font-size': '14.5px',
            'line-height': '1.8'
        });
        // 引用块内部的段落不要再叠段距
        var kids = el.querySelectorAll('div,p');
        for (var i = 0; i < kids.length; i++) {
            setStyle(kids[i], { 'margin': '0' });
        }
    }

    function beautifyText(body) {
        var nodes = body.querySelectorAll(
            'div,p,h1,h2,h3,h4,h5,h6,ul,ol,li,blockquote,pre,code,hr,img,a,input'
        );

        for (var i = 0; i < nodes.length; i++) {
            var el = nodes[i];
            var tag = el.tagName;

            if (tag === 'PRE') { polishCode(el); continue; }
            if (closest(el, 'pre')) { continue; }          // 代码块内部整体交给 pre
            if (tag === 'CODE') { styleCode(el); continue; }

            if (tag === 'HR') {
                setStyle(el, {
                    'border': '0',
                    'border-top': '1px solid #e2e8f0',
                    'margin': '22px 0',
                    'height': '0'
                });
                continue;
            }
            if (tag === 'IMG') {
                setStyle(el, {
                    'max-width': '100%',
                    'height': 'auto',
                    'border-radius': '6px',
                    'vertical-align': 'middle',
                    'margin': '6px 0'
                });
                continue;
            }
            if (tag === 'INPUT') {                       // Note Station 原生待办复选框
                setStyle(el, {
                    'vertical-align': '-2px',
                    'margin-right': '4px',
                    'border': '0'
                });
                continue;
            }
            if (tag === 'A') {
                setStyle(el, {
                    'color': '#2f6fd0',
                    'text-decoration': 'none',
                    'border-bottom': '1px solid #bcd6f5'
                });
                continue;
            }
            if (closest(el, 'table')) { continue; }        // 单元格内容由表格样式负责

            if (HEADS[tag]) { styleHeading(el, tag); continue; }
            if (tag === 'BLOCKQUOTE') { styleQuote(el); continue; }

            if (tag === 'UL' || tag === 'OL') {
                setStyle(el, {
                    'margin': '0 0 ' + P.gap,
                    'padding-left': P.indent,
                    'font-family': P.font,
                    'font-size': P.size,
                    'line-height': P.lh,
                    'color': P.color
                });
                continue;
            }
            if (tag === 'LI') {
                setStyle(el, {
                    'margin': P.listGap + ' 0',
                    'line-height': '1.8',
                    'font-family': P.font,
                    'font-size': P.size,
                    'color': P.color
                });
                continue;
            }

            // div / p 等普通块
            setStyle(el, {
                'margin': '0 0 ' + P.gap,
                'font-family': P.font,
                'font-size': P.size,
                'line-height': P.lh,
                'color': P.color
            });
        }

        // 顶边不要留白
        var first = body.firstElementChild;
        if (first) { setStyle(first, { 'margin-top': '0' }); }
    }

    /* ------------------------------------------------------------------ *
     * 轻量提示（不依赖 TinyMCE 皮肤）
     * ------------------------------------------------------------------ */
    function toast(editor, text) {
        try {
            var doc = editor.getContainer().ownerDocument;
            var d = doc.createElement('div');
            d.textContent = text;
            d.style.cssText = 'position:fixed;z-index:2147483000;top:64px;left:50%;' +
                'transform:translateX(-50%);background:rgba(38,52,66,.92);color:#fff;' +
                'font:13px/1.6 ' + SANS + ';padding:8px 18px;border-radius:18px;' +
                'box-shadow:0 6px 18px rgba(0,0,0,.18);pointer-events:none;' +
                'opacity:0;transition:opacity .18s ease';
            doc.body.appendChild(d);
            setTimeout(function () { d.style.opacity = '1'; }, 10);
            setTimeout(function () { d.style.opacity = '0'; }, 1500);
            setTimeout(function () {
                if (d.parentNode) { d.parentNode.removeChild(d); }
            }, 1850);
        } catch (e) { /* 提示失败无所谓 */ }
    }

    /* ------------------------------------------------------------------ *
     * 入口
     * ------------------------------------------------------------------ */
    function run(editor, tablesOnly) {
        var body = editor.getBody();
        if (!body) { return; }

        // 代码高亮会替换代码块内部的子节点，先存一个光标书签，跑完再还原
        var bookmark = null;
        try { bookmark = editor.selection.getBookmark(2, true); } catch (e) { /* ignore */ }

        editor.undoManager.transact(function () {
            var tables = body.querySelectorAll('table');
            for (var i = 0; i < tables.length; i++) {
                beautifyTable(tables[i]);
            }
            if (!tablesOnly) {
                beautifyText(body);
            }
        });

        if (bookmark) {
            try { editor.selection.moveToBookmark(bookmark); } catch (e2) { /* ignore */ }
        }

        try { editor.nodeChanged(); } catch (e) { /* ignore */ }
        try { editor.setDirty(true); } catch (e) { /* ignore */ }
        try { editor.fire('input'); } catch (e) { /* ignore */ }
        try { editor.fire('change'); } catch (e) { /* ignore */ }

        toast(editor, tablesOnly
            ? '表格已美化（⌘Z 可撤销）'
            : '排版 / 代码高亮 / 表格已美化（⌘Z 可撤销）');
    }

    // 工具栏图标：内联 SVG，深色实心（该按钮是动作按钮，无常驻开关状态）
    var ICON_URI_BT = 'data:image/svg+xml;base64,';

    function applyIcon(btn, uri) {
        try {
            var el = btn && btn.getEl && btn.getEl();
            if (!el) { return; }
            var ico = el.querySelector ? el.querySelector('.mce-ico') : null;
            if (!ico) {
                // 兜底：控件没生成图标节点时自己补一个，宽度与原生图标按钮一致
                var host = (el.querySelector && el.querySelector('button')) || el;
                ico = (el.ownerDocument || document).createElement('i');
                ico.className = 'mce-ico';
                host.insertBefore(ico, host.firstChild);
            }
            ico.style.backgroundImage = 'url("' + uri + '")';
            ico.style.backgroundSize = '20px 20px';
            ico.style.backgroundPosition = 'center center';
            ico.style.backgroundRepeat = 'no-repeat';
        } catch (err) { /* ignore */ }
    }

    tinymce.PluginManager.add('syno_beautify', function (editor) {
        editor.addButton('syno_beautify', {
            icon: 'none',
            image: ICON_URI_BT,
            onPostRender: function () {
                applyIcon(this, ICON_URI_BT);
            },
            tooltip: '一键美化：字体 / 行距 / 代码格式化+高亮 / 表格（按住 Option 仅美化表格）',
            onclick: function (e) {
                run(editor, !!(e && e.altKey));
            }
        });

        editor.addShortcut('ctrl+alt+b', '一键美化', function () {
            run(editor, false);
        });
    });
}());
